package evmxgo

import (
	"testing"

	converter "github.com/33cn/externaldb/convert"
	"github.com/33cn/externaldb/lib/schema"
	"github.com/33cn/externaldb/lib/util"
	"github.com/stretchr/testify/assert"
)

// findRecord 取第一条指定索引的记录；account/account_record 插入后位置不固定。
func findRecord(t *testing.T, records []schema.Record, index string) schema.Record {
	t.Helper()
	for _, r := range records {
		if r.Index() == index {
			return r
		}
	}
	keys := make([]string, 0, len(records))
	for _, r := range records {
		keys = append(keys, r.Key())
	}
	t.Fatalf("records 里没有索引 %q 的记录，实际: %v", index, keys)
	return nil
}

func TestConvert_ConvertTx(t *testing.T) {
	convert := NewConvert("", "bty", nil)
	schema.SetVersion(7)

	convertTokenBurn(t, convert)
	convertTokenMint(t, convert)
	convertTokenTransfer(t, convert)
	convertTokenTransferToExec(t, convert)
	convertTokenWithdraw(t, convert)
}

func convertTokenBurn(t *testing.T, convert converter.ExecConvert) {
	blockByte := ""
	env, err := util.GenEnv(blockByte, 0)
	assert.Nil(t, err)

	records, err := convert.ConvertTx(env, schema.OpAdd)
	assert.Nil(t, err)
	assert.Equal(t, 4, len(records))

	// burn：evmxgo_info 记录当前总供应量（fixture 里是 DOG）
	info := findRecord(t, records, "evmxgo_info")
	assert.Equal(t, "evmxgo_info/_doc/DOG", info.Key())
	assert.Equal(t, `{"amount":280000000}`, string(info.Value()))

}
func convertTokenMint(t *testing.T, convert converter.ExecConvert) {
	blockByte := ""
	env, err := util.GenEnv(blockByte, 0)
	assert.Nil(t, err)

	records, err := convert.ConvertTx(env, schema.OpAdd)
	assert.Nil(t, err)
	assert.Equal(t, 4, len(records))

	info := findRecord(t, records, "evmxgo_info")
	assert.Equal(t, "evmxgo_info/_doc/DOG", info.Key())
	assert.Equal(t, `{"amount":290000000}`, string(info.Value()))

}
func convertTokenTransfer(t *testing.T, convert converter.ExecConvert) {
	blockByte := ""
	env, err := util.GenEnv(blockByte, 0)
	assert.Nil(t, err)

	records, err := convert.ConvertTx(env, schema.OpAdd)
	assert.Nil(t, err)
	// 失败交易（receipt success=false）只写 transaction 记录，不展开资产变化
	assert.Equal(t, 1, len(records))
	assert.Equal(t, "transaction/_doc/0x7b1ae2b6b56508c7fc449f1760d12a19008c9975047dcfd6cf70354cf731fef7", records[0].Key())

}
func convertTokenTransferToExec(t *testing.T, convert converter.ExecConvert) {
	blockByte := ""
	env, err := util.GenEnv(blockByte, 0)
	assert.Nil(t, err)

	records, err := convert.ConvertTx(env, schema.OpAdd)
	assert.Nil(t, err)
	// 交易 + 3 对 account/account_record（转出方、合约内部账户、收款方）
	assert.Equal(t, 7, len(records))
	assert.Equal(t, "transaction/_doc/0x151ef68401a07151b3121b050314cb1b1727a67046fe74b160532685bec780ff", records[0].Key())
	// 合约内部账户的 exec 是 token 执行器地址
	assert.Equal(t, "account/_doc/1jQtMFpmEW2J4fgEG3opEoVzfSyMpBMaR-12hpJBHybh1mSyCijQ2MQJPk7z7kZ7jnQa-evmxgo:DOG", records[5].Key())

}
func convertTokenWithdraw(t *testing.T, convert converter.ExecConvert) {
	blockByte := ""
	env, err := util.GenEnv(blockByte, 0)
	assert.Nil(t, err)

	records, err := convert.ConvertTx(env, schema.OpAdd)
	assert.Nil(t, err)
	assert.Equal(t, 7, len(records))
	assert.Equal(t, "transaction/_doc/0xac14ecbd4819f0ee0ea0ff18bfea0b68315d907bb558e458695e87a613d5ab35", records[0].Key())

}
